import AbstractView from '../framework/view/abstract-view.js';
import {DateFormat} from '../const.js';
import {formatDate, getDurationInMinutes, formatDuration, capitalize, encodeHtml, getValidPointType} from '../utils.js';

function createOffersTemplate(offers) {
  if (offers.length === 0) {
    return '';
  }

  const items = offers.map(
    ({title, price}) =>
      /* HTML */ `<li class="event__offer">
        <span class="event__offer-title">${encodeHtml(title)}</span>
        &plus;&euro;&nbsp;
        <span class="event__offer-price">${encodeHtml(price)}</span>
      </li>`,
  );

  return /* HTML */ `<h4 class="visually-hidden">Offers:</h4>
    <ul class="event__selected-offers">
      ${items.join('')}
    </ul>`;
}

function createPointTemplate(point, destination, offers) {
  const {type, dateFrom, dateTo, basePrice, isFavorite} = point;
  const validPointType = getValidPointType(type);
  const selectedOffers = offers.filter((offer) => point.offers.includes(offer.id));
  const favoriteClassName = isFavorite ? 'event__favorite-btn--active' : '';

  return /* HTML */ `<li class="trip-events__item">
    <div class="event">
      <time class="event__date" datetime="${formatDate(dateFrom, 'YYYY-MM-DD')}"
        >${formatDate(dateFrom, DateFormat.POINT_DAY).toUpperCase()}</time
      >
      <div class="event__type">
        <img
          class="event__type-icon"
          width="42"
          height="42"
          src="img/icons/${validPointType}.png"
          alt="Event type icon"
        />
      </div>
      <h3 class="event__title">${capitalize(validPointType)} ${encodeHtml(destination?.name)}</h3>
      <div class="event__schedule">
        <p class="event__time">
          <time class="event__start-time" datetime="${formatDate(dateFrom, 'YYYY-MM-DDTHH:mm')}"
            >${formatDate(dateFrom, DateFormat.POINT_TIME)}</time
          >
          &mdash;
          <time class="event__end-time" datetime="${formatDate(dateTo, 'YYYY-MM-DDTHH:mm')}"
            >${formatDate(dateTo, DateFormat.POINT_TIME)}</time
          >
        </p>
        <p class="event__duration">${formatDuration(getDurationInMinutes(dateFrom, dateTo))}</p>
      </div>
      <p class="event__price">&euro;&nbsp;<span class="event__price-value">${encodeHtml(basePrice)}</span></p>
      ${createOffersTemplate(selectedOffers)}
      <button class="event__favorite-btn ${favoriteClassName}" type="button">
        <span class="visually-hidden">Add to favorite</span>
        <svg class="event__favorite-icon" width="28" height="28" viewBox="0 0 28 28">
          <path
            d="M14 21l-8.22899 4.3262 1.57159-9.1631L.685209 9.67376 9.8855 8.33688 14 0l4.1145 8.33688 9.2003 1.33688-6.6574 6.48934 1.5716 9.1631L14 21z"
          />
        </svg>
      </button>
      <button class="event__rollup-btn" type="button">
        <span class="visually-hidden">Open event</span>
      </button>
    </div>
  </li>`;
}

export default class PointView extends AbstractView {
  #point = null;
  #destination = null;
  #offers = [];
  #handleEditClick = null;
  #handleFavoriteClick = null;

  constructor({point, destination, offers, onEditClick, onFavoriteClick}) {
    super();
    this.#point = point;
    this.#destination = destination;
    this.#offers = offers;
    this.#handleEditClick = onEditClick;
    this.#handleFavoriteClick = onFavoriteClick;

    this.element.querySelector('.event__rollup-btn').addEventListener('click', this.#rollupButtonClickHandler);
    this.element.querySelector('.event__favorite-btn').addEventListener('click', this.#favoriteButtonClickHandler);
  }

  get template() {
    return createPointTemplate(this.#point, this.#destination, this.#offers);
  }

  #rollupButtonClickHandler = (evt) => {
    evt.preventDefault();
    this.#handleEditClick();
  };

  #favoriteButtonClickHandler = (evt) => {
    evt.preventDefault();
    this.#handleFavoriteClick();
  };
}
